pub fn available_from(id:DefId)->Option<u8>{ROWS.iter().filter(|row|row.id==id).map(|row|row.epoch).min()}
pub fn available_until(id:DefId)->Option<u8>{ROWS.iter().filter(|row|row.id==id).map(|row|row.until).max()}
